static inline float sigmoid_f(float x)
{
    return 1.0f / (1.0f + expf(-x));
}

static inline float ridge_predict_proba(const float* x)
{
    float s = ridge_intercept;

    for (int i = 0; i < N_FEATURES; i++)
    {
        s += x[i] * ridge_coef[i];
    }

    return sigmoid_f(s);
}

